To solve this problem, we can define a dictionary of homophone pairs and their correct spellings. Then, we can traverse through the input passage and replace any homophone words with their correct counterparts from our dictionary.

Here's how we can implement this solution in Swift:

```swift
let homophones: [String: String] = [
    "there": "they're",
    "their": "there",
    "they're": "their",
    "too": ["to", "two"] // 'too' has multiple meanings, so we store them in an array
]

func replaceHomophones(in text: String) -> String {
    var result = ""
    for char in text {
        let prevChar = result.suffix(1).first ?? " "
        let word = String(characters: text.prefix(text.index($0 == " ", where: { !prevChar.isWhitespace })!) + " ")
        let correctedWord = correctHomophones(word)
        result += correctedWord
    }
    return result
}

func correctHomophones(_ word: String) -> String {
    let lowercasedWord = word.lowercased()
    for (homophone, replacements) in homophones {
        for replacement in replacements {
            if lowercasedWord.hasPrefix(homophone.lowercased()) && lowercasedWord.count > homophone.count {
                return String(replacement + String(lowercasedWord[homophone.count..<lowercasedWord.index(of: " ", offset: homophone.count)]))
            }
        }
    }
    return word
}

