```cpp
#include <iostream>
#include <nlohmann/json.hpp>

void bubbleSort(int arr[], int n) {
    bool swapped = true;
    for (size_t i = 0; i < n - 1 && swapped; ++i) {
        swapped = false;
        for (size_t j = 0; j < n - I - 1; ++j) {
            if (arr[j] > arr[j+1]) {
                std::swap(arr[j], arr[j+1]);
                swapped = true;
            }
        }
    }
}

int main() {
    std::string jsonString = R"({
      "array": [5, 2, 9, 1, 5, 6]
    })";

    nlohmann::json obj;
    obj = nlohmann::json::parse(jsonString);

    int arr[obj["array"].size()];
    int i = 0;
    for (auto& elem : obj["array"]) {
        arr[i++] = elem.get<int>();
    }

    bubbleSort(arr, obj["array"].size());

    std::cout << "Sorted Array: ";
    for (auto& elem : obj["array"]) {
        std::cout << elem.get<int>() << " ";
    }
    std::cout << "\n";

    return 0;
}
```

