Here's an example of a generic REST service wrapper class in C# with authentication token handling:

```csharp
using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace RestServiceWrapper
{
    public abstract class RestServiceWrapperBase : IDisposable
    {
        private readonly string baseUrl;
        private readonly string authorizationHeader;
        private readonly HttpClient httpClient;
        private bool disposedValue;

        protected RestServiceWrapperBase(string baseUrl, string authorizationHeader)
        {
            this.baseUrl = baseUrl;
            this.authorizationHeader = authorizationHeader;
            httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromSeconds(60); // Set timeout to 60 seconds by default
        }

        protected async Task<TResult> SendRequestAsync<TResult>(string endpoint, HttpMethod method, CancellationToken cancellationToken = default)
        {
            var requestUri = new Uri($"{baseUrl}/{endpoint}");
            var requestMessage = new HttpRequestMessage(method, requestUri)
            {
                Headers = { { "Authorization", authorizationHeader } },
            };
            using (var requestContent = PrepareRequestContent())
            {
                requestMessage.Content = requestContent;
            }
            var response = await httpClient.SendAsync(requestMessage, cancellationToken).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadFromJsonAsync<TResult>();
        }

        protected virtual HttpContent PrepareRequestContent() => null;

        protected void Dispose(bool disposing)
        {
            if (!disposedValue)
            {
                if (disposing)
                {
                    httpClient.Dispose();
                }
                disposedValue = true;
            }
        }

        public void Dispose()
        {
            Dispose(true);
            GC.SuppressFinalize(this);
        }
    }

    public sealed class RestServiceWrapper : RestServiceWrapperBase

